INSERT INTO `counting_numbers_p2_parts` (doc_id,counter_name,scope_key,batch,value) SELECT target_id,tupleElement(item,1),unhex('37613162323532313934626466666531373835643538656339353161363538616531333064353264313963386165656366353236626134383130306636396336'),7,tupleElement(item,2) FROM (SELECT target_id,arrayJoin([tuple(unhex('636f6d6d656e7473'),countIf(1))]) AS item FROM (SELECT *,JSONExtractString(body,unhex('706f73745f6964')) AS target_id FROM (SELECT d.doc_id, d.author_key, d.posted_by, d.body, d.ref_value, d.tags, d.created_at, d.updated_at, d.ad_mode, d.ad_target, dg.group_id FROM (SELECT doc_id, author_key, posted_by, body, ref_value, tags, created_at, updated_at, ad_mode, ad_target FROM (SELECT doc_id, author_key, posted_by, body, ref_value, tags, created_at, updated_at, ad_mode, ad_target, deleted, row_number() OVER (PARTITION BY doc_id, author_key ORDER BY updated_at DESC) AS rn FROM satellite_batch_fixture_documents WHERE collection_name = 'comments' AND cityHash64(doc_id) % 8 = 7) WHERE rn = 1 AND deleted = 0) AS d JOIN (SELECT doc_id, group_id FROM (SELECT doc_id, group_id, deleted, row_number() OVER (PARTITION BY doc_id, group_id ORDER BY updated_at DESC) AS rn FROM satellite_batch_fixture_links WHERE group_id IN ('allowed', 'second') AND cityHash64(doc_id) % 8 = 7) WHERE rn = 1 AND deleted = 0) AS dg ON d.doc_id = dg.doc_id WHERE NOT (d.author_key IN (SELECT user_key FROM (SELECT user_key, blocked_key, deleted, row_number() OVER (PARTITION BY user_key, blocked_key ORDER BY updated_at DESC, deleted DESC) AS rn FROM user_blacklist) WHERE rn = 1 AND deleted = 0 AND blocked_key = 'fixture-reader')) AND NOT ((d.author_key, dg.group_id) IN (SELECT user_key, group_id FROM (SELECT user_key, group_id, blocked_key, deleted, row_number() OVER (PARTITION BY user_key, group_id, blocked_key ORDER BY updated_at DESC, deleted DESC) AS rn FROM group_blacklist) WHERE rn = 1 AND deleted = 0 AND blocked_key = 'fixture-reader')) AND NOT (d.author_key <> 'fixture-reader' AND (d.author_key, dg.group_id) IN (SELECT user_key, group_id FROM (SELECT user_key, group_id, sharing_enabled, deleted, row_number() OVER (PARTITION BY user_key, group_id ORDER BY updated_at DESC) AS rn FROM user_group_sharing) WHERE rn = 1 AND deleted = 0 AND sharing_enabled = 0)) AND NOT ((d.doc_id, dg.group_id) IN (SELECT doc_id, group_id FROM (SELECT group_id, doc_id, deleted, row_number() OVER (PARTITION BY group_id, doc_id ORDER BY updated_at DESC, deleted DESC) AS rn FROM group_hidden_docs) WHERE rn = 1 AND deleted = 0)) AND NOT (d.author_key IN (SELECT username FROM (SELECT username, deleted, row_number() OVER (PARTITION BY username ORDER BY updated_at DESC, deleted DESC) AS rn FROM banned_users) WHERE rn = 1 AND deleted = 0)))) WHERE target_id!='' GROUP BY target_id) WHERE tupleElement(item,2)>0
